-- HR Genius Oracle schema. Run with the HR_GENIUS schema owner.
CREATE TABLE DEPARTMENTS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, DEPARTMENT_NAME VARCHAR2(100) NOT NULL UNIQUE, DESCRIPTION VARCHAR2(500));
CREATE TABLE DESIGNATIONS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, TITLE VARCHAR2(120) NOT NULL, GRADE_LEVEL NUMBER(3), DESCRIPTION VARCHAR2(500));
CREATE TABLE EMPLOYEES (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_CODE VARCHAR2(30) NOT NULL UNIQUE, FIRST_NAME VARCHAR2(80) NOT NULL, LAST_NAME VARCHAR2(80) NOT NULL, DATE_OF_BIRTH DATE, GENDER VARCHAR2(30), EMAIL VARCHAR2(160) NOT NULL UNIQUE, PHONE VARCHAR2(30), ADDRESS VARCHAR2(500), HIRE_DATE DATE, DEPARTMENT_ID NUMBER REFERENCES DEPARTMENTS(ID), DESIGNATION_ID NUMBER REFERENCES DESIGNATIONS(ID), MANAGER_ID NUMBER REFERENCES EMPLOYEES(ID), STATUS VARCHAR2(20) DEFAULT 'ACTIVE' NOT NULL);
CREATE INDEX IDX_EMP_DEPT ON EMPLOYEES(DEPARTMENT_ID);
CREATE INDEX IDX_EMP_STATUS ON EMPLOYEES(STATUS);
CREATE TABLE EMPLOYMENT_HISTORY (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), COMPANY_NAME VARCHAR2(140) NOT NULL, ROLE VARCHAR2(120), START_DATE DATE, END_DATE DATE, NOTES VARCHAR2(1000));
CREATE TABLE EDUCATION_QUALIFICATIONS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), DEGREE VARCHAR2(120) NOT NULL, INSTITUTION VARCHAR2(160), YEAR_OF_PASSING NUMBER(4), NOTES VARCHAR2(1000));
CREATE TABLE JOB_REQUISITIONS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, DEPARTMENT_ID NUMBER NOT NULL REFERENCES DEPARTMENTS(ID), DESIGNATION_ID NUMBER NOT NULL REFERENCES DESIGNATIONS(ID), REQUESTED_BY NUMBER NOT NULL REFERENCES EMPLOYEES(ID), OPENINGS NUMBER NOT NULL CHECK(OPENINGS>0), STATUS VARCHAR2(30) DEFAULT 'PENDING_APPROVAL' NOT NULL, OPEN_DATE DATE, JOB_DESCRIPTION VARCHAR2(2000));
CREATE TABLE CANDIDATES (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, REQUISITION_ID NUMBER NOT NULL REFERENCES JOB_REQUISITIONS(ID), FIRST_NAME VARCHAR2(80) NOT NULL, LAST_NAME VARCHAR2(80) NOT NULL, EMAIL VARCHAR2(160) NOT NULL, RESUME_REF VARCHAR2(500), STAGE VARCHAR2(30) DEFAULT 'APPLIED' NOT NULL);
CREATE TABLE INTERVIEWS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CANDIDATE_ID NUMBER NOT NULL REFERENCES CANDIDATES(ID), INTERVIEWER_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), INTERVIEW_DATE TIMESTAMP NOT NULL, ROUND VARCHAR2(40), FEEDBACK VARCHAR2(2000), RESULT VARCHAR2(30) DEFAULT 'PENDING');
CREATE TABLE ATTENDANCE_RECORDS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), ATTENDANCE_DATE DATE NOT NULL, CHECK_IN TIMESTAMP, CHECK_OUT TIMESTAMP, STATUS VARCHAR2(20), CONSTRAINT UQ_ATTENDANCE_DAY UNIQUE(EMPLOYEE_ID,ATTENDANCE_DATE));
CREATE TABLE LEAVE_TYPES (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, TYPE_NAME VARCHAR2(60) NOT NULL UNIQUE, ANNUAL_QUOTA NUMBER(4) NOT NULL, CARRY_FORWARD NUMBER(1) DEFAULT 0);
CREATE TABLE LEAVE_REQUESTS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), LEAVE_TYPE_ID NUMBER NOT NULL REFERENCES LEAVE_TYPES(ID), FROM_DATE DATE NOT NULL, TO_DATE DATE NOT NULL, REASON VARCHAR2(1000), STATUS VARCHAR2(20) DEFAULT 'PENDING' NOT NULL, APPROVED_BY NUMBER REFERENCES EMPLOYEES(ID), APPROVAL_COMMENT VARCHAR2(1000), CONSTRAINT CK_LEAVE_DATES CHECK(TO_DATE>=FROM_DATE));
CREATE INDEX IDX_LEAVE_STATUS ON LEAVE_REQUESTS(STATUS);
CREATE TABLE SALARY_COMPONENTS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, COMPONENT_NAME VARCHAR2(80) NOT NULL UNIQUE, TYPE VARCHAR2(20) NOT NULL CHECK(TYPE IN ('EARNING','DEDUCTION')), TAXABLE NUMBER(1) DEFAULT 0);
CREATE TABLE EMPLOYEE_SALARY (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), COMPONENT_ID NUMBER NOT NULL REFERENCES SALARY_COMPONENTS(ID), AMOUNT NUMBER(12,2) NOT NULL CHECK(AMOUNT>=0), EFFECTIVE_FROM DATE NOT NULL);
CREATE TABLE PAYROLL (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), PAY_PERIOD VARCHAR2(7) NOT NULL, GROSS_PAY NUMBER(12,2) NOT NULL, TOTAL_DEDUCTIONS NUMBER(12,2) NOT NULL, NET_PAY NUMBER(12,2) NOT NULL, PROCESSED_DATE DATE, STATUS VARCHAR2(20) DEFAULT 'LOCKED' NOT NULL, CONSTRAINT UQ_PAYROLL_EMP_PERIOD UNIQUE(EMPLOYEE_ID,PAY_PERIOD));
CREATE INDEX IDX_PAYROLL_PERIOD ON PAYROLL(PAY_PERIOD);
CREATE TABLE PERFORMANCE_REVIEWS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, EMPLOYEE_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), REVIEWER_ID NUMBER NOT NULL REFERENCES EMPLOYEES(ID), REVIEW_CYCLE VARCHAR2(30) NOT NULL, RATING NUMBER(3,2) CHECK(RATING BETWEEN 0 AND 5), STRENGTHS VARCHAR2(2000), IMPROVEMENT_AREAS VARCHAR2(2000), GOALS VARCHAR2(2000), REVIEW_DATE DATE);
CREATE TABLE ROLES (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ROLE_NAME VARCHAR2(40) NOT NULL UNIQUE, DESCRIPTION VARCHAR2(300));
CREATE TABLE USERS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, USERNAME VARCHAR2(80) NOT NULL UNIQUE, PASSWORD_HASH VARCHAR2(255) NOT NULL, EMPLOYEE_ID NUMBER UNIQUE REFERENCES EMPLOYEES(ID), ROLE_ID NUMBER NOT NULL REFERENCES ROLES(ID), ACTIVE NUMBER(1) DEFAULT 1 NOT NULL);
CREATE TABLE AUDIT_LOGS (ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ENTITY_NAME VARCHAR2(100) NOT NULL, ENTITY_ID VARCHAR2(80) NOT NULL, ACTION VARCHAR2(20) NOT NULL, ACTOR VARCHAR2(100), OCCURRED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, DETAILS VARCHAR2(2000));
